INSERT INTO "condensador_modelos" ("id", "linha_id", "modelo", "fpi", "qtd_ventiladores", "diametro_ventilador_mm", "vazao_ar_m3h", "polos_ou_rpm", "tipo_motor", "num_fileiras", "capacidade_kcal_h", "potencia_kw", "corrente_220v", "corrente_380v", "corrente_460v", "ruido_db", "carga_refrigerante_kg", "coletor_entrada_pol", "coletor_saida_pol", "peso_liquido_kg", "peso_bruto_kg", "comprimento_mm", "largura_mm", "altura_mm", "num_fixacoes", "nomenclatura_compra", "descricao_comercial", "imagem_path") VALUES (145, 2, 'ACV057', 10, 1, 800.0, NULL, '6', 'AC', 3, 57300.0, 2.5, 7.58, 4.66, 4.73, 44.0, 4.3, '1 5/8', '1 5/8', 230.0, 255.0, 1.476, 1.098, 1.416, NULL, NULL, 'Os condensadores remotos planos Elgin, nas versões AC e EC, foram desenvolvidos para aplicações comerciais e industriais que exigem elevada eficiência na rejeição de calor, baixo nível de ruído, confiabilidade operacional e facilidade de instalação. Sua construção robusta, associada a componentes de alta qualidade e geometria otimizada de troca térmica, proporciona excelente desempenho em sistemas de refrigeração e ar-condicionado operando com diversos fluidos refrigerantes. Fabricados com serpentinas em tubos de cobre e aletas de alumínio de alta eficiência, os condensadores Elgin garantem elevada capacidade de dissipação térmica, reduzindo a temperatura de condensação e contribuindo diretamente para o aumento do rendimento do sistema frigorífico. A menor pressão de condensação resulta em redução do consumo de energia elétrica, menor esforço dos compressores e maior vida útil dos componentes do circuito frigorífico. A linha está disponível em duas configurações de ventilação, permitindo adequar o equipamento às necessidades específicas de cada projeto. Os modelos AC utilizam motores de corrente alternada (AC), oferecendo uma solução robusta, econômica e amplamente consolidada no mercado. São indicados para instalações onde a simplicidade construtiva, a facilidade de manutenção e o excelente custo-benefício são fatores determinantes. Já os modelos EC empregam motores eletronicamente comutados (Electronically Commutated), tecnologia que proporciona ganhos significativos em eficiência energética, controle preciso da velocidade de ventilação e redução dos níveis de ruído. A modulação contínua da rotação permite que o condensador opere apenas com a capacidade necessária em cada condição de carga térmica, reduzindo o consumo de energia, minimizando oscilações de pressão de condensação e proporcionando maior estabilidade operacional, especialmente em aplicações com controle eletrônico da condensação. O projeto mecânico da linha contempla gabinete em chapa de aço galvanizado com pintura eletrostática de alta resistência à corrosão, tornando os equipamentos adequados para instalação em ambientes externos e sujeitos às condições climáticas mais severas. Sua configuração plana facilita o transporte, a movimentação e a instalação em coberturas, áreas técnicas e locais com restrições de espaço. Disponíveis em diversas capacidades frigoríficas, os condensadores remotos Elgin podem ser aplicados em câmaras frigoríficas, supermercados, centros de distribuição, indústrias alimentícias, laticínios, frigoríficos, hospitais, laboratórios, cozinhas industriais, centros logísticos refrigerados e inúmeras outras aplicações que demandam elevada confiabilidade operacional.', NULL);
INSERT INTO "condensador_modelos" ("id", "linha_id", "modelo", "fpi", "qtd_ventiladores", "diametro_ventilador_mm", "vazao_ar_m3h", "polos_ou_rpm", "tipo_motor", "num_fileiras", "capacidade_kcal_h", "potencia_kw", "corrente_220v", "corrente_380v", "corrente_460v", "ruido_db", "carga_refrigerante_kg", "coletor_entrada_pol", "coletor_saida_pol", "peso_liquido_kg", "peso_bruto_kg", "comprimento_mm", "largura_mm", "altura_mm", "num_fixacoes", "nomenclatura_compra", "descricao_comercial", "imagem_path") VALUES (146, 2, 'ACV067', 10, 1, 800.0, NULL, '6', 'AC', 4, 67300.0, 2.5, 7.58, 4.66, 4.73, 44.0, 6.0, '1 5/8', '1 5/8', 230.0, 255.0, 1.476, 1.098, 1.416, NULL, NULL, 'Os condensadores remotos planos Elgin, nas versões AC e EC, foram desenvolvidos para aplicações comerciais e industriais que exigem elevada eficiência na rejeição de calor, baixo nível de ruído, confiabilidade operacional e facilidade de instalação. Sua construção robusta, associada a componentes de alta qualidade e geometria otimizada de troca térmica, proporciona excelente desempenho em sistemas de refrigeração e ar-condicionado operando com diversos fluidos refrigerantes. Fabricados com serpentinas em tubos de cobre e aletas de alumínio de alta eficiência, os condensadores Elgin garantem elevada capacidade de dissipação térmica, reduzindo a temperatura de condensação e contribuindo diretamente para o aumento do rendimento do sistema frigorífico. A menor pressão de condensação resulta em redução do consumo de energia elétrica, menor esforço dos compressores e maior vida útil dos componentes do circuito frigorífico. A linha está disponível em duas configurações de ventilação, permitindo adequar o equipamento às necessidades específicas de cada projeto. Os modelos AC utilizam motores de corrente alternada (AC), oferecendo uma solução robusta, econômica e amplamente consolidada no mercado. São indicados para instalações onde a simplicidade construtiva, a facilidade de manutenção e o excelente custo-benefíci